<?php
require __DIR__.'/bootstrap.php';

if(isset($_GET['api'])){require_login();header('Content-Type: application/json; charset=utf-8');if($_GET['api']==='products'){$q='%'.trim($_GET['q']??'').'%';$cid=(int)($_GET['customer_id']??0);$s=$pdo->prepare('SELECT p.id,p.english_name,p.tamil_name,p.unit,p.default_rate,COALESCE(c.name,"") category,(SELECT bi.rate FROM bill_items bi JOIN bills b ON b.id=bi.bill_id WHERE bi.product_id=p.id AND b.customer_id=? AND b.status="active" ORDER BY b.created_at DESC,b.id DESC,bi.id DESC LIMIT 1) customer_last_rate,(SELECT b.created_at FROM bill_items bi JOIN bills b ON b.id=bi.bill_id WHERE bi.product_id=p.id AND b.customer_id=? AND b.status="active" ORDER BY b.created_at DESC,b.id DESC,bi.id DESC LIMIT 1) customer_last_date FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.active=1 AND p.english_name LIKE ? ORDER BY CASE WHEN p.english_name=? THEN 0 ELSE 1 END,p.english_name LIMIT 15');$exact=trim($_GET['q']??'');$s->execute([$cid,$cid,$q,$exact]);echo json_encode($s->fetchAll(),JSON_UNESCAPED_UNICODE);}elseif($_GET['api']==='product_history'){$cid=(int)($_GET['customer_id']??0);$pid=(int)($_GET['product_id']??0);$s=$pdo->prepare('SELECT b.bill_no,b.created_at,bi.quantity,bi.rate FROM bill_items bi JOIN bills b ON b.id=bi.bill_id WHERE bi.product_id=? AND b.customer_id=? AND b.status="active" ORDER BY b.created_at DESC,b.id DESC,bi.id DESC LIMIT 5');$s->execute([$pid,$cid]);echo json_encode($s->fetchAll(),JSON_UNESCAPED_UNICODE);}exit;}
$page=$_GET['page']??(logged_in()?'dashboard':'login');
if($page==='logout'){session_destroy();redirect('?page=login');}
if($page==='login'&&$_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare('SELECT * FROM users WHERE username=?');$s->execute([trim($_POST['username']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];redirect('index.php');}flash('Incorrect username or password.','error');redirect('?page=login');}
if($page!=='login'&&$page!=='public_bill')require_login();

if($_SERVER['REQUEST_METHOD']==='POST'&&$page!=='login'){
 check_csrf();$action=$_POST['action']??'';
 try{
  if($action==='save_category'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');if($name==='')throw new RuntimeException('Category name is required.');if($id){$s=$pdo->prepare('UPDATE categories SET name=?,active=? WHERE id=?');$s->execute([$name,isset($_POST['active'])?1:0,$id]);}else{$s=$pdo->prepare('INSERT INTO categories(name) VALUES(?)');$s->execute([$name]);}flash('Category saved.');redirect('?page=categories');}
  if($action==='save_product'){$id=(int)($_POST['id']??0);$vals=[(int)$_POST['category_id']?:null,trim($_POST['english_name']),trim($_POST['tamil_name']),trim($_POST['unit']),max(0,(float)$_POST['default_rate']),isset($_POST['active'])?1:0];if($vals[1]===''||$vals[2]==='')throw new RuntimeException('English and Tamil names are required.');if($id){$vals[]=$id;$s=$pdo->prepare('UPDATE products SET category_id=?,english_name=?,tamil_name=?,unit=?,default_rate=?,active=? WHERE id=?');}else{$s=$pdo->prepare('INSERT INTO products(category_id,english_name,tamil_name,unit,default_rate,active) VALUES(?,?,?,?,?,?)');}$s->execute($vals);flash('Product saved.');redirect('?page=products');}
  if($action==='save_customer'){$id=(int)($_POST['id']??0);$opening=(float)($_POST['opening_balance']??0);if(!is_finite($opening))throw new RuntimeException('Enter a valid opening balance.');$vals=[trim($_POST['name']),normalize_mobile($_POST['mobile']??''),trim($_POST['address']??''),$opening];if($vals[0]==='')throw new RuntimeException('Customer name is required.');if($id){$vals[]=$id;$s=$pdo->prepare('UPDATE customers SET name=?,mobile=?,address=?,opening_balance=? WHERE id=?');}else{$s=$pdo->prepare('INSERT INTO customers(name,mobile,address,opening_balance) VALUES(?,?,?,?)');}$s->execute($vals);flash('Customer saved.');redirect('?page=customers');}
  if($action==='save_payment'){$cid=(int)($_POST['customer_id']??0);$amount=(float)($_POST['amount']??0);if($cid<1||!is_finite($amount)||$amount<=0)throw new RuntimeException('Select a customer and enter a valid payment.');$s=$pdo->prepare('SELECT id FROM customers WHERE id=?');$s->execute([$cid]);if(!$s->fetchColumn())throw new RuntimeException('Selected customer was not found.');$s=$pdo->prepare('INSERT INTO payments(customer_id,amount,note) VALUES(?,?,?)');$s->execute([$cid,$amount,trim($_POST['note']??'')]);flash('Payment recorded.');redirect('?page=payments');}
  if($action==='reverse_payment'){$id=(int)($_POST['id']??0);$pdo->beginTransaction();$s=$pdo->prepare('SELECT * FROM payments WHERE id=? FOR UPDATE');$s->execute([$id]);$payment=$s->fetch();if(!$payment||(float)$payment['amount']<=0||str_starts_with($payment['note'],'[REVERSED]'))throw new RuntimeException('This payment cannot be reversed.');$pdo->prepare('UPDATE payments SET note=CONCAT("[REVERSED] ",note) WHERE id=?')->execute([$id]);$s=$pdo->prepare('INSERT INTO payments(customer_id,amount,note) VALUES(?,?,?)');$s->execute([$payment['customer_id'],-(float)$payment['amount'],'Reversal of payment #'.$id]);$pdo->commit();flash('Payment reversed and customer balance restored.');redirect('?page=payments');}
  if($action==='save_bill'){
   $billId=(int)($_POST['bill_id']??0);$cid=(int)($_POST['customer_id']??0);if($cid<1)throw new RuntimeException('Select a customer.');$billDateRaw=trim($_POST['bill_date']??'');$billDateCheck=DateTime::createFromFormat('Y-m-d',$billDateRaw);if(!$billDateCheck||$billDateCheck->format('Y-m-d')!==$billDateRaw)throw new RuntimeException('Select a valid bill date.');$billTimestamp=$billDateRaw.' '.date('H:i:s');$items=[];$sum=0;
   $productLookup=$pdo->prepare('SELECT id,english_name,tamil_name,unit FROM products WHERE id=? AND active=1');
   foreach($_POST['english_name']??[] as $i=>$english){$row=$i+1;$english=trim($english);$productId=(int)($_POST['product_id'][$i]??0);$qty=(float)($_POST['quantity'][$i]??0);$rate=(float)($_POST['rate'][$i]??0);if($english===''&&$productId===0)continue;if($productId<1&&$english!==''){$s=$pdo->prepare('SELECT id FROM products WHERE active=1 AND english_name=? LIMIT 1');$s->execute([$english]);$productId=(int)$s->fetchColumn();}if($productId<1)throw new RuntimeException("Choose {$english} from the product list in row {$row}.");if(!is_finite($qty)||$qty<=0)throw new RuntimeException("Enter a valid quantity in row {$row}.");if(!is_finite($rate)||$rate<0)throw new RuntimeException("Enter a valid non-negative rate in row {$row}.");$productLookup->execute([$productId]);$product=$productLookup->fetch();if(!$product)throw new RuntimeException("The selected product in row {$row} is unavailable.");$amount=round($qty*$rate,2);if(!is_finite($amount)||$amount<0)throw new RuntimeException("Invalid amount in row {$row}.");$sum=round($sum+$amount,2);$items[]=[$productId,$product['english_name'],$product['tamil_name'],$qty,$product['unit'],$rate,$amount];}
   if(!$items)throw new RuntimeException('Add at least one valid product.');$received=(float)($_POST['amount_received']??0);if(!is_finite($received)||$received<0)throw new RuntimeException('Enter a valid amount received.');if($received>$sum)throw new RuntimeException('Amount received cannot exceed the bill total.');$pdo->beginTransaction();
   if($billId){$s=$pdo->prepare('UPDATE bills SET customer_id=?,subtotal=?,amount_received=?,created_at=?,status="active" WHERE id=?');$s->execute([$cid,$sum,$received,$billTimestamp,$billId]);$pdo->prepare('DELETE FROM bill_items WHERE bill_id=?')->execute([$billId]);}
   else{$s=$pdo->query('SELECT setting_value FROM settings WHERE setting_key="next_bill_no" FOR UPDATE');$next=(int)($s->fetchColumn()?:1);$s=$pdo->prepare('INSERT INTO bills(bill_no,customer_id,subtotal,amount_received,share_token,created_at) VALUES(?,?,?,?,?,?)');$s->execute([$next,$cid,$sum,$received,bin2hex(random_bytes(32)),$billTimestamp]);$billId=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE settings SET setting_value=? WHERE setting_key="next_bill_no"')->execute([(string)($next+1)]);}
   $s=$pdo->prepare('INSERT INTO bill_items(bill_id,product_id,english_name,tamil_name,quantity,unit,rate,amount) VALUES(?,?,?,?,?,?,?,?)');foreach($items as $item)$s->execute(array_merge([$billId],$item));if(supports_bill_balance_snapshot($pdo)){$closing=round(customer_balance($pdo,$cid),2);$pdo->prepare('UPDATE bills SET closing_balance=? WHERE id=?')->execute([$closing,$billId]);}$pdo->commit();flash('Bill saved.');redirect('?page=view_bill&id='.$billId);
  }
  if($action==='cancel_bill'){$id=(int)$_POST['id'];$pdo->prepare('UPDATE bills SET status="cancelled" WHERE id=?')->execute([$id]);flash('Bill cancelled; customer balance updated.');redirect('?page=bills');}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e->getMessage(),'error');redirect($_SERVER['HTTP_REFERER']??'index.php');}
}

