function footer_html(): void {?></main><script src="assets/app.js?v=20260831-21"></script></body></html><?php }

if($page==='login'){header_html('Sign in');?><div class="card login"><h1>SGAS</h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><p><label>Username</label><input name="username" autocomplete="username" required autofocus></p><p><label>Password</label><input type="password" name="password" autocomplete="current-password" required></p><button>Sign in</button></form></div><?php footer_html();exit;}

if($page==='dashboard'){header_html('Dashboard');$customers=(int)$pdo->query('SELECT COUNT(*) FROM customers')->fetchColumn();$products=(int)$pdo->query('SELECT COUNT(*) FROM products WHERE active=1')->fetchColumn();$bills=(int)$pdo->query("SELECT COUNT(*) FROM bills WHERE status='active'")->fetchColumn();?><h1>Business Overview</h1><p class="muted" style="margin-top:-17px;margin-bottom:24px">Welcome back. Here is your SGAS billing summary.</p><div class="grid stats"><div class="card stat">Total Customers<b><?=$customers?></b></div><div class="card stat">Active Products<b><?=$products?></b></div><div class="card stat">Total Bills<b><?=$bills?></b></div></div><div class="card"><h2>Quick Actions</h2><div class="actions"><a class="btn" href="?page=new_bill">＋ Create New Bill</a><a class="btn secondary" href="?page=customers">Record Customer Payment</a><a class="btn secondary" href="?page=products">Add New Product</a></div></div><?php footer_html();exit;}

if($page==='categories'){$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM categories WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$rows=$pdo->query('SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();header_html('Categories');?><h1>Product Categories</h1><div class="grid"><div class="card"><h2><?=$edit?'Edit':'Add'?> Category</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_category"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><p><label>Category name</label><input name="name" value="<?=e($edit['name']??'')?>" required></p><?php if($edit):?><p><label><input style="width:auto" type="checkbox" name="active" <?=$edit['active']?'checked':''?>> Active</label></p><?php endif;?><button>Save Category</button></form></div><div class="card"><h2>Categories</h2><table><tr><th>Name</th><th>Products</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=$r['product_count']?></td><td><a href="?page=categories&edit=<?=$r['id']?>">Edit</a></td></tr><?php endforeach;?></table></div></div><?php footer_html();exit;}

if($page==='products'){$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$cats=$pdo->query('SELECT * FROM categories WHERE active=1 ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.english_name')->fetchAll();header_html('Products');?><h1>Products</h1><div class="card"><h2><?=$edit?'Edit':'Add'?> Product</h2><form method="post" class="grid"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_product"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><p><label>Category</label><select name="category_id"><option value="0">No category</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($edit['category_id']??0)==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></p><p><label>English name (search)</label><input name="english_name" value="<?=e($edit['english_name']??'')?>" required></p><p><label>Tamil name (print)</label><input lang="ta" name="tamil_name" value="<?=e($edit['tamil_name']??'')?>" required></p><p><label>Unit</label><input name="unit" value="<?=e($edit['unit']??'Nos')?>" required></p><p><label>Default rate</label><input type="number" step="0.01" min="0" name="default_rate" value="<?=e($edit['default_rate']??'0')?>"></p><p><label><input style="width:auto" type="checkbox" name="active" <?=!$edit||$edit['active']?'checked':''?>> Active</label><br><button>Save Product</button></p></form></div><div class="card"><table><tr><th>English search name</th><th>Tamil print name</th><th>Category</th><th>Unit</th><th>Rate</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['english_name'])?></td><td lang="ta"><?=e($r['tamil_name'])?></td><td><?=e($r['category'])?></td><td><?=e($r['unit'])?></td><td><?=money($r['default_rate'])?></td><td><a href="?page=products&edit=<?=$r['id']?>">Edit</a></td></tr><?php endforeach;?></table></div><?php footer_html();exit;}

if($page==='customers'){$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM customers WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$rows=$pdo->query('SELECT * FROM customers ORDER BY name')->fetchAll();header_html('Customers');?><h1>Customers & Balances</h1><div class="grid"><div class="card"><h2><?=$edit?'Edit':'Add'?> Customer</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_customer"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><p><label>Name</label><input name="name" value="<?=e($edit['name']??'')?>" required></p><p><label>WhatsApp Number</label><input name="mobile" inputmode="tel" placeholder="9677811194" value="<?=e($edit['mobile']??'')?>"><small class="muted">Enter a 10-digit Indian number. +91 is added automatically.</small></p><p><label>Address</label><textarea name="address"><?=e($edit['address']??'')?></textarea></p><p><label>Opening balance</label><input type="number" step="0.01" name="opening_balance" value="<?=e($edit['opening_balance']??'0')?>"></p><button>Save Customer</button></form></div><div class="card"><h2>Record Payment</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_payment"><p><label>Customer</label><select name="customer_id" required><option value="">Select</option><?php foreach($rows as $r):?><option value="<?=$r['id']?>"><?=e($r['name'])?></option><?php endforeach;?></select></p><p><label>Amount received</label><input type="number" min="0.01" step="0.01" name="amount" required></p><p><label>Note</label><input name="note"></p><button>Record Payment</button> <a class="btn secondary" href="?page=payments">Payment History</a></form></div></div><div class="card"><table><tr><th>Customer</th><th>WhatsApp</th><th class="right">Balance</th><th>Actions</th></tr><?php foreach($rows as $r):$bal=customer_balance($pdo,(int)$r['id']);$msg=str_replace(['{name}','{balance}'],[$r['name'],money($bal)],setting($pdo,'reminder_tamil'));$phone=whatsapp_number($r['mobile']);?><tr><td><?=e($r['name'])?></td><td><?php if($phone):?>+<?=e($phone)?> <span class="status-ready">Ready</span><?php elseif($r['mobile']):?><span class="status-check">Check number</span><?php else:?>—<?php endif;?></td><td class="right">₹<?=money($bal)?></td><td class="actions"><a href="?page=customers&edit=<?=$r['id']?>">Edit</a><a href="?page=ledger&customer_id=<?=$r['id']?>">Ledger</a><?php if($phone):?><a target="_blank" href="https://wa.me/<?=e($phone)?>?text=<?=rawurlencode($msg)?>">WhatsApp Reminder</a><?php endif;?></td></tr><?php endforeach;?></table></div><?php footer_html();exit;}

if($page==='ledger'){$customers=$pdo->query('SELECT id,name,mobile FROM customers ORDER BY name')->fetchAll();$customerId=(int)($_GET['customer_id']??0);$ledger=$customerId?customer_ledger($pdo,$customerId):['customer'=>null,'rows'=>[],'balance'=>0];$customer=$ledger['customer'];header_html('Customer Ledger');?><div class="actions no-print"><h1 style="margin-right:auto">Customer Ledger</h1></div><form method="get" class="card no-print ledger-search"><input type="hidden" name="page" value="ledger"><div class="grid"><p><label>Search customer</label><input id="ledger-customer-search" placeholder="Type customer name"></p><p><label>Select customer</label><select id="ledger-customer" name="customer_id" required><option value="">Choose customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>" data-name="<?=e(strtolower($c['name']))?>" <?=$customerId===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></p></div><button>View Ledger</button></form><?php if($customer):$phone=whatsapp_number($customer['mobile']);$msg=str_replace(['{name}','{balance}'],[$customer['name'],money($ledger['balance'])],setting($pdo,'reminder_tamil'));$pdfName='SGAS-Ledger-'.preg_replace('/[^A-Za-z0-9_-]+/','-',$customer['name']).'.pdf';?><div class="actions no-print ledger-actions"><button onclick="downloadDocumentPdf('<?=e($pdfName)?>')">Download PDF</button><button onclick="shareDocumentPdf('<?=e($pdfName)?>')">Share PDF</button><?php if($phone):?><a class="btn" target="_blank" href="https://wa.me/<?=e($phone)?>?text=<?=rawurlencode($msg)?>">WhatsApp Balance</a><?php endif;?></div><div class="card pdf-document ledger-print"><div class="ledger-header"><div><h1>SGAS</h1><p>Customer Ledger Statement</p></div><div><b><?=e($customer['name'])?></b><br><?=e($customer['mobile'])?><br><?=nl2br(e($customer['address']))?></div></div><table><thead><tr><th>Date</th><th>Type</th><th>Reference</th><th>Details</th><th class="right">Debit</th><th class="right">Credit</th><th class="right">Balance</th></tr></thead><tbody><?php foreach($ledger['rows'] as $r):?><tr><td><?=$r['timestamp']?e(date('d-m-Y',strtotime($r['timestamp']))):'—'?></td><td><?=e($r['type'])?></td><td><?=e($r['reference'])?></td><td><?=e($r['note'])?></td><td class="right"><?=$r['delta']>0?'₹'.money($r['delta']):'—'?></td><td class="right"><?=$r['delta']<0?'₹'.money(abs($r['delta'])):'—'?></td><td class="right"><b>₹<?=money($r['balance'])?></b></td></tr><?php endforeach;?></tbody></table><div class="ledger-closing"><span>Closing Balance</span><b>₹<?=money($ledger['balance'])?></b></div></div><script src="https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js"></script><?php endif;footer_html();exit;}

if($page==='payments'){$rows=$pdo->query('SELECT p.*,c.name customer FROM payments p JOIN customers c ON c.id=p.customer_id ORDER BY p.id DESC LIMIT 500')->fetchAll();header_html('Payments');?><div class="actions"><h1 style="margin-right:auto">Payment History</h1><a class="btn secondary" href="?page=customers">Record Payment</a></div><div class="card"><p class="muted">Reversals preserve the original record and restore the customer balance.</p><table><tr><th>ID</th><th>Customer</th><th>Recorded</th><th>Note</th><th class="right">Amount</th><th>Status</th><th></th></tr><?php foreach($rows as $r):$reversal=(float)$r['amount']<0;$reversed=str_starts_with($r['note'],'[REVERSED]');?><tr><td>#<?=$r['id']?></td><td><?=e($r['customer'])?></td><td><?=e(date('d-m-Y h:i A',strtotime($r['created_at'])))?></td><td><?=e($r['note'])?></td><td class="right <?=$reversal?'reversal-amount':''?>">₹<?=money($r['amount'])?></td><td><?=$reversal?'Reversal':($reversed?'Reversed':'Active')?></td><td><?php if(!$reversal&&!$reversed):?><form method="post" onsubmit="return confirm('Reverse this payment and restore the customer balance?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="reverse_payment"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger">Reverse</button></form><?php endif;?></td></tr><?php endforeach;?></table></div><?php footer_html();exit;}

if($page==='new_bill'||$page==='edit_bill'){$bill=null;$existing=[];if($page==='edit_bill'){$s=$pdo->prepare('SELECT * FROM bills WHERE id=?');$s->execute([(int)$_GET['id']]);$bill=$s->fetch();if(!$bill)exit('Bill not found.');$s=$pdo->prepare('SELECT * FROM bill_items WHERE bill_id=?');$s->execute([$bill['id']]);$existing=$s->fetchAll();}$customers=$pdo->query('SELECT * FROM customers ORDER BY name')->fetchAll();$selectedCustomer=null;foreach($customers as $candidate){if(($bill['customer_id']??0)==$candidate['id']){$selectedCustomer=$candidate;break;}}$displayBillNo=$bill?(int)$bill['bill_no']:(int)setting($pdo,'next_bill_no','1');$displayBillDate=$bill?date('Y-m-d',strtotime($bill['created_at'])):date('Y-m-d');header_html($bill?'Edit Bill':'New Bill');?><div class="page-heading"><div><h1><?=$bill?'Edit Bill #'.str_pad($bill['bill_no'],4,'0',STR_PAD_LEFT):'New Bill'?></h1></div></div><div class="price-popup" id="price-history-popup" hidden><div class="price-popup-card"><div class="price-popup-head"><div><small>Customer Price History</small><h3 id="price-popup-title">Last 5 Bills</h3></div><button type="button" class="price-popup-close" aria-label="Close">×</button></div><div class="price-popup-body"><table><thead><tr><th>Bill No.</th><th>Date</th><th class="right">Qty</th><th class="right">Rate</th><th></th></tr></thead><tbody id="price-popup-rows"></tbody></table></div></div></div><form method="post" class="card bill-form" id="bill-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_bill"><input type="hidden" name="bill_id" value="<?=e($bill['id']??'')?>"><div class="bill-top"><div class="customer-area"><div class="customer-search-row"><div class="customer-field searchbox"><label>Customer Name</label><input id="bill-customer-search" placeholder="Type customer name or mobile" autocomplete="off" value="<?=e($selectedCustomer['name']??'')?>" required><input type="hidden" id="bill-customer" name="customer_id" value="<?=e($selectedCustomer['id']??'')?>" data-balance="<?=$selectedCustomer?customer_balance($pdo,(int)$selectedCustomer['id'],$bill['id']??null):0?>"><div class="suggestions customer-suggestions" id="customer-suggestions"><?php foreach($customers as $c):$cb=customer_balance($pdo,(int)$c['id'],$bill['id']??null);?><button type="button" data-id="<?=$c['id']?>" data-name="<?=e($c['name'])?>" data-mobile="<?=e($c['mobile'])?>" data-address="<?=e($c['address'])?>" data-search="<?=e(strtolower($c['name'].' '.$c['mobile']))?>" data-balance="<?=$cb?>"><strong><?=e($c['name'])?></strong><small><?=e($c['mobile'])?><?=$cb!=0?' · Balance ₹'.money($cb):''?></small></button><?php endforeach;?></div></div><a class="btn secondary add-customer-link" href="?page=customers">＋ Add Customer</a></div><div class="customer-details" id="customer-details" <?=$selectedCustomer?'':'hidden'?>> <div class="customer-avatar" id="customer-avatar"><?=e($selectedCustomer?strtoupper(substr($selectedCustomer['name'],0,2)):'')?></div><div><b id="customer-detail-name"><?=e($selectedCustomer['name']??'')?></b><span id="customer-detail-mobile"><?=$selectedCustomer&&$selectedCustomer['mobile']?'WhatsApp: '.e($selectedCustomer['mobile']):'WhatsApp: —'?></span><span id="customer-detail-address"><?=$selectedCustomer&&trim($selectedCustomer['address'])!==''?'Address: '.e($selectedCustomer['address']):'Address: —'?></span><span>Previous Balance: ₹<strong id="customer-detail-balance"><?=money($selectedCustomer?customer_balance($pdo,(int)$selectedCustomer['id'],$bill['id']??null):0)?></strong></span></div></div></div><div class="bill-info-stack"><div><label>Bill Date</label><input type="date" name="bill_date" value="<?=e($displayBillDate)?>" required></div><div><small>Bill No.</small><b>#<?=str_pad((string)$displayBillNo,4,'0',STR_PAD_LEFT)?></b></div></div></div><div class="items-table-head"><span>S.No</span><span>Product (English Search)</span><span>Qty</span><span>Unit</span><span>Rate</span><span>Amount</span><span></span></div><div id="items"></div><div class="bill-footer"><div class="bill-summary"><div><small>Previous Balance</small><b>₹<span id="previous-balance">0.00</span></b></div><div><small>Current Bill</small><b>₹<span id="subtotal">0.00</span></b></div><div><label>Amount Received</label><input id="bill-received" type="number" name="amount_received" min="0" step="0.01" value="<?=e($bill['amount_received']??'0')?>"></div><div class="closing-box"><small>Closing Balance</small><b>₹<span id="closing-balance">0.00</span></b></div></div><div class="bill-actions"><a class="btn secondary" href="<?=$bill?'?page=bills':'index.php'?>">Cancel</a><button class="save-bill"><?=$bill?($bill['status']==='cancelled'?'Save & Restore Bill':'Save Changes'):'Save & Create Bill'?></button></div></div></form><template id="item-template"><div class="item-row"><div class="sno-cell"><label>S.No</label><b class="row-number">1</b></div><div class="product-cell searchbox"><label>Product</label><input class="product-search" name="english_name[]" autocomplete="off" required><input type="hidden" class="product-id" name="product_id[]"><input type="hidden" class="tamil-name" name="tamil_name[]"><div class="suggestions"></div><small class="price-history" hidden></small></div><div><label>Qty</label><input class="qty numeric" name="quantity[]" type="number" min="0.001" step="0.001" value="1"></div><div><label>Unit</label><input class="unit" name="unit[]" readonly></div><div><label>Rate</label><input class="rate numeric" name="rate[]" type="number" min="0" step="0.01"></div><div><label>Amount</label><input class="amount numeric" readonly></div><button type="button" class="danger remove" aria-label="Remove row">×</button></div></template><?php if($existing):?><script>window.addEventListener('DOMContentLoaded',()=>{<?php foreach($existing as $x):?>addRow(<?=json_encode(['product_id'=>$x['product_id'],'english_name'=>$x['english_name'],'tamil_name'=>$x['tamil_name'],'unit'=>$x['unit'],'default_rate'=>$x['rate']],JSON_UNESCAPED_UNICODE)?>);let r=document.querySelector('#items .item-row:last-child');r.querySelector('.qty').value=<?=json_encode($x['quantity'])?>;recalc();<?php endforeach;?>});</script><?php endif;footer_html();exit;}

if($page==='bills'){$rows=$pdo->query('SELECT b.*,c.name customer FROM bills b JOIN customers c ON c.id=b.customer_id ORDER BY b.id DESC')->fetchAll();header_html('Bills');?><div class="actions"><h1 style="margin-right:auto">Bills</h1><a class="btn" href="?page=new_bill">New Bill</a></div><div class="card"><table><tr><th>Bill No.</th><th>Date</th><th>Customer</th><th class="right">Total</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=str_pad($r['bill_no'],4,'0',STR_PAD_LEFT)?></td><td><?=e(date('d-m-Y',strtotime($r['created_at'])))?></td><td><?=e($r['customer'])?></td><td class="right">₹<?=money($r['subtotal'])?></td><td><?=e(ucfirst($r['status']))?></td><td><div class="actions bill-row-actions"><a class="btn secondary" href="?page=view_bill&id=<?=$r['id']?>">View / Print</a><?php if($r['status']==='active'):?><a class="btn" href="?page=edit_bill&id=<?=$r['id']?>">Edit</a><?php else:?><a class="btn" href="?page=edit_bill&id=<?=$r['id']?>" onclick="return confirm('Editing and saving will restore this cancelled bill and update the customer balance. Continue?')">Edit & Restore</a><?php endif;?></div></td></tr><?php endforeach;?></table></div><?php footer_html();exit;}

if($page==='view_bill'||$page==='public_bill'){$public=$page==='public_bill';if($public){$s=$pdo->prepare('SELECT b.*,c.name customer,c.mobile,c.address FROM bills b JOIN customers c ON c.id=b.customer_id WHERE b.share_token=? AND b.status="active"');$s->execute([$_GET['token']??'']);}else{$s=$pdo->prepare('SELECT b.*,c.name customer,c.mobile,c.address FROM bills b JOIN customers c ON c.id=b.customer_id WHERE b.id=?');$s->execute([(int)$_GET['id']]);}$bill=$s->fetch();if(!$bill)exit('Bill not found.');$s=$pdo->prepare('SELECT * FROM bill_items WHERE bill_id=?');$s->execute([$bill['id']]);$items=$s->fetchAll();$balance=isset($bill['closing_balance'])&&$bill['closing_balance']!==null?(float)$bill['closing_balance']:customer_balance($pdo,(int)$bill['customer_id']);$shareUrl=$config['base_url'].'/?page=public_bill&token='.$bill['share_token'];$billPhone=whatsapp_number($bill['mobile']);$pdfName='SGAS-Bill-'.str_pad($bill['bill_no'],4,'0',STR_PAD_LEFT).'.pdf';header_html('Bill #'.$bill['bill_no']);?><div class="actions no-print"><?php if(!$public):?><a class="btn secondary" href="?page=bills">Back</a><?php if($bill['status']==='active'):?><a class="btn" href="?page=edit_bill&id=<?=$bill['id']?>">Edit</a><?php endif;?><?php endif;?><button onclick="downloadBillPdf('<?=e($pdfName)?>')">Download PDF</button><button onclick="shareBillPdf('<?=e($pdfName)?>')">Share PDF</button><?php if(!$public&&$billPhone):?><button onclick="shareBillToCustomer('<?=e($billPhone)?>','SGAS Bill #<?=str_pad($bill['bill_no'],4,'0',STR_PAD_LEFT)?>','<?=e($shareUrl)?>')">WhatsApp Customer</button><?php elseif(!$public):?><a class="btn secondary" href="?page=customers&edit=<?=$bill['customer_id']?>">Add WhatsApp Number</a><?php endif;?></div><div class="card bill-print"><h1>SGAS</h1><?php if($bill['status']==='cancelled'):?><div class="notice error no-print">CANCELLED</div><?php endif;?><div class="grid"><div><b>Bill No:</b> <?=str_pad($bill['bill_no'],4,'0',STR_PAD_LEFT)?><br><b>Bill Date:</b> <?=e(date('d-m-Y',strtotime($bill['created_at'])))?></div><div><b>Customer:</b> <?=e($bill['customer'])?><br><?=nl2br(e($bill['address']))?><br><?=e($bill['mobile'])?></div></div><br><table><thead><tr><th>S.No</th><th>பொருள்</th><th class="right">அளவு</th><th>அலகு</th><th class="right">விலை</th><th class="right">தொகை</th></tr></thead><tbody><?php foreach($items as $i=>$x):?><tr><td><?=$i+1?></td><td lang="ta"><?=e($x['tamil_name'])?></td><td class="right"><?=rtrim(rtrim(number_format($x['quantity'],3),'0'),'.')?></td><td><?=e($x['unit'])?></td><td class="right"><?=money($x['rate'])?></td><td class="right"><?=money($x['amount'])?></td></tr><?php endforeach;?></tbody></table><table class="summary"><tr><td>மொத்தம்</td><td class="right">₹<?=money($bill['subtotal'])?></td></tr><?php if((float)$bill['amount_received']>0):?><tr><td>பெற்ற தொகை</td><td class="right">₹<?=money($bill['amount_received'])?></td></tr><?php endif;?><tr><td><b>வாடிக்கையாளர் நிலுவை</b></td><td class="right"><b>₹<?=money($balance)?></b></td></tr></table></div><script src="https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js"></script><?php footer_html();exit;}

